<div class="welcome-row"><div><div class="form-kicker">ORGANIZAÇÃO FINANCEIRA</div><h1>Contas</h1><p class="page-subtitle">Acompanhe saldos e movimentações de cada conta.</p></div><a class="button primary" href="/accounts">＋ Nova conta</a></div>
<?php if(!empty($errors)): ?><div class="alert error"><?=e(implode(' ',$errors))?></div><?php endif; ?>
<?php if($statement): ?>
<section class="panel statement-panel"><div class="panel-head"><div><a class="text-link" href="/accounts">← Voltar às contas</a><h3 style="margin-top:12px"><?=e($statement['name'])?> · Extrato</h3><p>Saldo atual: <strong><?=money((int)$statement['balance'])?></strong></p></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Descrição</th><th>Categoria / tipo</th><th>Status</th><th class="right">Valor</th></tr></thead><tbody><?php foreach($statementRows as $row): $positive=in_array($row['type'],['income','transfer_in'],true); ?><tr><td><?=e(date('d/m/Y',strtotime($row['date'])))?></td><td><?=e($row['description'])?></td><td><?=e($row['category'])?></td><td><span class="status-pill <?=e($row['status'])?>"><?=e(match($row['status']){'paid'=>'Paga','received'=>'Recebida','pending'=>'Pendente',default=>'Transferida'})?></span></td><td class="right <?= $positive?'amount-in':'amount-out' ?>"><?= $positive?'+':'−' ?><?=money((int)$row['amount'])?></td></tr><?php endforeach; ?><?php if(!$statementRows): ?><tr><td colspan="5" class="table-empty">Ainda não há movimentações nesta conta.</td></tr><?php endif; ?></tbody></table></div></section>
<?php else: ?>
<div class="account-summary"><div><span>Saldo consolidado</span><strong><?=money(array_sum(array_map(fn($a)=>(int)$a['balance'],$accounts)))?></strong></div><span><?=count(array_filter($accounts,fn($a)=>(int)$a['is_active']===1))?> contas ativas</span></div>
<div class="account-grid"><?php foreach($accounts as $account): ?><article class="account-card"><div class="account-card-top"><span class="account-color" style="background:<?=e($account['color'])?>"></span><div class="account-card-title"><strong><?=e($account['name'])?></strong><small><?=e($types[$account['type']]??'Conta')?><?= $account['institution']?' · '.e($account['institution']):'' ?></small></div><span class="account-menu">•••</span></div><div class="account-balance-label">Saldo atual</div><div class="account-balance"><?=money((int)$account['balance'])?></div><div class="account-card-bottom"><a href="/accounts?statement=<?=(int)$account['id']?>">Ver extrato →</a><div><a href="/accounts?edit=<?=(int)$account['id']?>">Editar</a><form method="post" action="/accounts/toggle"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$account['id']?>"><button><?= $account['is_active']?'Desativar':'Ativar' ?></button></form></div></div></article><?php endforeach; ?><?php if(!$accounts): ?><div class="empty-account"><span class="empty-icon">▤</span><strong>Comece adicionando uma conta</strong><p>Cadastre sua conta corrente, carteira ou conta digital para acompanhar seu saldo.</p></div><?php endif; ?></div>
<?php endif; ?>
<section class="panel editor-panel" id="account-form"><div class="panel-head"><div><h3><?=$edit?'Editar conta':'Adicionar conta'?></h3><p>Informe os dados iniciais. O saldo é calculado a partir da data-base.</p></div></div><form method="post" action="/accounts/save" class="data-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><label>Nome da conta<input name="name" required maxlength="80" value="<?=e($edit['name']??'')?>" placeholder="Ex.: Conta principal"></label><label>Tipo<select name="type" required><?php foreach($types as $key=>$label): ?><option value="<?=e($key)?>" <?=($edit['type']??'checking')===$key?'selected':''?>><?=e($label)?></option><?php endforeach; ?></select></label><label>Instituição financeira<input name="institution" maxlength="100" value="<?=e($edit['institution']??'')?>" placeholder="Opcional"></label><label>Saldo inicial<input name="opening_balance" inputmode="decimal" required value="<?=e(isset($edit['opening_balance'])?money_input((int)$edit['opening_balance']):'0,00')?>" placeholder="0,00"></label><label>Data do saldo inicial<input type="date" name="opening_date" required value="<?=e($edit['opening_date']??date('Y-m-d'))?>"></label><label>Cor<input type="color" name="color" value="<?=e($edit['color']??'#168b68')?>"></label><label class="span-two">Descrição<input name="description" maxlength="200" value="<?=e($edit['description']??'')?>" placeholder="Opcional"></label><div class="form-actions"><button class="button primary" type="submit">Salvar conta</button><?php if($edit): ?><a class="button secondary" href="/accounts">Cancelar</a><?php endif; ?></div></form></section>
